"""Generate a "lib" dist flake (ca-rewrite or ia-signed) from evaluated
package metadata and (for ca-rewrite) the old->new path maps.

Store paths are written split in two so that the generated files contain no
32-character store hash: Nix's reference scanner would otherwise make the
dist (and so the server) retain every packaged path.
"""

import argparse
import json
import os
import shutil


def split(path, store_dir):
    base = path[len(store_dir) + 1 :]
    return [base[:16], base[16:]]


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--mode", required=True, choices=["ca-rewrite", "ia-signed"])
    ap.add_argument("--pre", required=True)
    ap.add_argument("--map", action="append", default=[], help="variant=file")
    ap.add_argument("--outputs-nix", required=True)
    ap.add_argument("--description", default="")
    ap.add_argument("--out", required=True)
    args = ap.parse_args()

    store_dir = os.environ.get("NIX_STORE", "/nix/store")
    pre = json.load(open(args.pre))
    maps = {}
    for m in args.map:
        v, f = m.split("=", 1)
        maps[v] = json.load(open(f))
    variants = list(maps) if args.mode == "ca-rewrite" else []
    if args.mode == "ca-rewrite" and not variants:
        raise SystemExit("ca-rewrite needs at least one --map")

    ids = {}
    paths = {}
    packages = {}
    for system, pkgs in sorted(pre["packages"].items()):
        out_pkgs = packages.setdefault(system, {})
        for name, info in sorted(pkgs.items()):
            pkg_paths = {}
            dirs = {}
            for output, path in sorted(info["paths"].items()):
                if path not in ids:
                    pid = str(len(ids))
                    ids[path] = pid
                    entry = {}
                    if args.mode == "ca-rewrite":
                        for v in variants:
                            if path not in maps[v]:
                                raise SystemExit(f"{path} missing from {v} map")
                            entry[v] = split(maps[v][path], store_dir)
                    else:
                        entry["ia"] = split(path, store_dir)
                    paths[pid] = entry
                pkg_paths[output] = ids[path]
                dirs[output] = os.path.isdir(path) and not os.path.islink(path)
            out_pkgs[name] = {
                "name": info["name"],
                "pname": info.get("pname"),
                "version": info.get("version"),
                "meta": info.get("meta", {}),
                "outputs": info["outputs"],
                "outputsToInstall": info["outputsToInstall"],
                "paths": pkg_paths,
                "dirs": dirs,
            }

    os.makedirs(args.out)
    data = {"mode": args.mode, "variants": variants, "paths": paths, "packages": packages}
    with open(os.path.join(args.out, "packages.json"), "w") as f:
        json.dump(data, f, indent=1, sort_keys=True)
        f.write("\n")
    shutil.copyfile(args.outputs_nix, os.path.join(args.out, "outputs.nix"))
    nix_desc = json.dumps(args.description).replace("${", "\\${")
    with open(os.path.join(args.out, "flake.nix"), "w") as f:
        f.write(
            "# Generated by flake-in-a-box. Consumed through the per-host wrapper\n"
            "# flake, which calls lib.mkOutputs with the URL of its binary cache.\n"
            "{\n"
            f"  description = {nix_desc};\n"
            "  outputs = { self }: {\n"
            "    lib.mkOutputs = { cacheUrl }: import ./outputs.nix {\n"
            "      inherit cacheUrl;\n"
            "      data = builtins.fromJSON (builtins.readFile ./packages.json);\n"
            "    };\n"
            "  };\n"
            "}\n"
        )


if __name__ == "__main__":
    main()
